export type ReplayCommand = { type: "watchLive"; payload: LiveReplayTarget } | { type: "trackLive"; payload: {
	target: LiveReplayTarget,
	action: LiveReplayTrackingAction,
} } | { type: "cancelLiveTracking" } |
/**
 *  Play a `.fafreplay`/`.scfareplay` file by path: used both for the
 *  file-picker flow and for watching a [`LocalReplay`] row.
 */
{ type: "openFile"; payload: {
	path: string,
} } |
/**
 *  Search the vault. A default [`ReplayQuery`] is the unfiltered
 *  newest-first feed the tab opens with, so this covers both "browse" and
 *  "search" without a second command.
 */
{ type: "searchVault"; payload: {
	/**
	 *  Boxed: `ReplayQuery` is a wide struct of strings, and every clone of
	 *  an event/command would otherwise carry it inline. Transparent on the
	 *  wire: serde and specta both see straight through the box.
	 */
	query: ReplayQuery,
} } |
/**  Fetch the featured-mod list for the search form's mod filter. */
{ type: "loadFeaturedMods" } |
/**  Download and play a vault replay by its game id. */
{ type: "watchVault"; payload: {
	uid: number,
} } |
/**
 *  Download a vault replay into the shared local replay library without
 *  launching Forged Alliance.
 */
{ type: "downloadVault"; payload: {
	uid: number,
} } |
/**  Scan the shared FAF replay folder for local `.fafreplay` files. */
{ type: "loadLocal" } |
/**
 *  Permanently remove one replay from the shared replay folder. The port
 *  validates that the resolved file is directly inside that folder.
 */
{ type: "deleteLocal"; payload: {
	path: string,
} };

/**
 *  The independent download-to-library lifecycle. Downloading a replay must
 *  not pretend that FA is launching (`ReplayStatus`) or that the online search
 *  is refreshing (`VaultStatus`), so it has its own small state machine.
 */
export type ReplayDownloadStatus = { type: "idle" } | { type: "downloading"; payload: {
	uid: number,
} } | { type: "downloaded"; payload: {
	uid: number,
	path: string,
} } | { type: "failed"; payload: {
	uid: number,
	reason: string,
} };

export type ReplayEvent = { type: "connecting" } |
/**
 *  `warning` carries a non-fatal prep-step issue (see
 *  [`ReplayState::last_warning`]): `None` when prep was clean/skipped.
 */
{ type: "playing"; payload: {
	uid: number | null,
	warning: string | null,
} } | { type: "failed"; payload: {
	reason: string,
} } |
/**
 *  The replay session ended (game process exited / stream closed): back
 *  to idle so the UI can start another one.
 */
{ type: "closed" } | { type: "liveTrackingScheduled"; payload: {
	tracking: LiveReplayTracking,
} } | { type: "liveTrackingCleared" } | { type: "vaultLoading" } | { type: "vaultLoaded"; payload: {
	replays: VaultReplay[],
	/**
	 *  The query these results answer, echoed back so the view and the
	 *  results can never disagree about what is being shown (paging in
	 *  particular reads the page number from here, not from the form).
	 *  Boxed: `ReplayQuery` is a wide struct of strings, and every clone of
	 *  an event/command would otherwise carry it inline. Transparent on the
	 *  wire: serde and specta both see straight through the box.
	 */
	query: ReplayQuery,
	/**  Whether a further page is likely to exist: a full page came back. */
	hasMore: boolean,
	totalPages?: number | null,
	totalRecords?: number | null,
} } | { type: "vaultLoadFailed"; payload: {
	reason: string,
} } |
/**  The featured-mod list backing the vault search's mod filter. */
{ type: "featuredModsLoaded"; payload: {
	mods: string[],
} } | { type: "localLoading" } | { type: "localLoaded"; payload: {
	replays: LocalReplay[],
} } | { type: "localDeleted"; payload: {
	path: string,
} } | { type: "vaultDownloadStarted"; payload: {
	uid: number,
} } | { type: "vaultDownloaded"; payload: {
	uid: number,
	replay: LocalReplay,
} } | { type: "vaultDownloadFailed"; payload: {
	uid: number,
	reason: string,
} } | { type: "localLoadFailed"; payload: {
	reason: string,
} };

export type ReplayPlayer = {
	name: string,
	/**
	 *  1=UEF, 2=Aeon, 3=Cybran, 4=Seraphim, 5=Random: the lobby selection
	 *  recorded by `playerStats.faction`, not the faction Random resolved to.
	 */
	faction: number | null,
	/**
	 *  `round(mean - 3*deviation)` at game time, the same "displayed rating"
	 *  formula the Python and Java clients use.
	 */
	rating: number | null,
	/**
	 *  Server-recorded game result (`VICTORY`, `DEFEAT`, `DRAW`, ...).
	 *  Empty when older games did not record an outcome.
	 */
	outcome: string,
	/**  Simulation score at the end of the game, when recorded. */
	score: number | null,
};

/**
 *  Everything the vault search can be narrowed by.
 *
 *  Empty string / `None` means "don't filter on this", so a default query is
 *  the unfiltered newest-first feed the tab opens with. Strings rather than
 *  richer types for the free-text fields: they come straight from input boxes,
 *  and the API matches them as glob patterns.
 */
export type ReplayQuery = {
	/**  Player login. Substring by default, exact when [`Self::exact_player`]. */
	player: string,
	/**  The Python client's "match username exactly" checkbox. */
	exactPlayer: boolean,
	map: string,
	mapAuthor: string,
	/**  The host-chosen lobby title (`game.attributes.name`). */
	title: string,
	/**
	 *  A specific replay id. Free text so a blank field is "any"; a
	 *  non-numeric value simply matches nothing.
	 */
	replayId: string,
	/**  The player who hosted the game. */
	host: string,
	/**
	 *  Featured mod technical names (`faf`, `ladder1v1`, …). Empty = any.
	 *  A list, not one value: the Java client's mod filter is a checkbox list.
	 */
	featuredMods: string[],
	/**  Leaderboard technical names (`ladder_1v1`, `global`, …). Empty = any. */
	leaderboards: string[],
	/**  Factions any player took: 1=UEF, 2=Aeon, 3=Cybran, 4=Seraphim. */
	factions: number[],
	/**  Victory conditions, from [`VICTORY_CONDITIONS`]. Empty = any. */
	victoryConditions: string[],
	/**  Displayed rating bounds, inclusive. */
	minRating: number | null,
	maxRating: number | null,
	/**  Average review score bounds, 0–5. */
	minReviewScore: number | null,
	maxReviewScore: number | null,
	/**  Game duration bounds in minutes. */
	minDurationMinutes: number | null,
	maxDurationMinutes: number | null,
	/**  The map's player-slot count. */
	mapMinPlayers: number | null,
	mapMaxPlayers: number | null,
	/**  Map edge length in km (the API stores pixels; see [`MAP_PIXELS_PER_KM`]). */
	mapMinSizeKm: number | null,
	mapMaxSizeKm: number | null,
	/**  Only maps that are ranked (`mapVersion.ranked`). */
	rankedMapOnly: boolean,
	/**
	 *  Inclusive date bounds on `startTime`, as `YYYY-MM-DD` or a full
	 *  RFC 3339 instant. Empty = unbounded.
	 */
	after: string,
	before: string,
	/**  Only games that counted for rating (`validity == VALID`). */
	onlyRanked: boolean,
	sortBy: ReplaySortField,
	sortDescending: boolean,
	/**  1-based, matching the API's `page[number]`. */
	page: number,
	pageSize: number,
};

/**
 *  Which property the results are ordered by. The sortable subset of the Java
 *  client's `GAME_PROPERTY_MAPPING` (its `Property::sortable` flag).
 */
export type ReplaySortField = "startTime" | "endTime" | "duration" | "reviewScore" | "title" | "id" | "victoryCondition";

export type ReplayState = {
	status: ReplayStatus,
	/**
	 *  A non-fatal issue from the last launch's prep steps (engine
	 *  version/map staging: see `infra/game_updater.rs`), e.g. "could not
	 *  stage map X". `None` means the last launch's prep was clean or none
	 *  has happened yet. Separate from [`ReplayStatus::Failed`], which is
	 *  for launches that didn't happen at all: this is for ones that did,
	 *  but might misbehave in FA itself (stuck loading screen, etc.) because
	 *  a non-fatal prep step failed. Cleared on the next [`ReplayEvent::Connecting`].
	 */
	lastWarning: string | null,
	/**
	 *  At most one delayed live replay is tracked, matching the Java client:
	 *  scheduling another replaces the previous choice.
	 */
	liveTracking: LiveReplayTracking | null,
	vault: VaultReplay[],
	vaultStatus: VaultStatus,
	/**
	 *  The query the current [`Self::vault`] results answer. The search *form*
	 *  is local to the view (a text box that dispatched on every keystroke
	 *  would be absurd); this is the last query actually executed, which is
	 *  what paging and the "showing results for…" summary read.
	 */
	vaultQuery: ReplayQuery,
	/**  Whether another page of results is likely to exist. */
	vaultHasMore: boolean,
	vaultTotalPages: number | null,
	vaultTotalRecords: number | null,
	/**
	 *  Saving an online replay to the shared local replay library is separate
	 *  from watching it and from loading either catalogue.
	 */
	downloadStatus: ReplayDownloadStatus,
	/**  Featured mod technical names, for the search form's mod filter. */
	featuredMods: string[],
	local: LocalReplay[],
	localStatus: VaultStatus,
};

export type ReplayStatus = { type: "idle" } | { type: "connecting" } |
/**
 *  FA has been launched. `uid` is `None` for a local file whose header
 *  failed to parse (playback still proceeds; we just can't label it).
 */
{ type: "playing"; payload: {
	uid: number | null,
} } | { type: "failed"; payload: {
	reason: string,
} };

export type ReplayTeam = {
	team: number,
	players: ReplayPlayer[],
};

export type ReportHistoryStatus = { type: "idle" } | { type: "loading" } | { type: "ready" } | { type: "failed"; payload: {
	reason: string,
} };

export type ReportStatus = { type: "idle" } | { type: "submitting" } | { type: "submitted" } | { type: "failed"; payload: {
	reason: string,
} };

export type ReportingCommand = { type: "open"; payload: {
	playerId: number,
	login: string,
} } | { type: "close" } | { type: "loadHistory" } | { type: "submit"; payload: {
	playerId: number,
	login: string,
	description: string,
	gameId: number | null,
	incidentTime: string,
} };

export type ReportingEvent = { type: "opened"; payload: {
	playerId: number,
	login: string,
} } | { type: "closed" } | { type: "submitting" } | { type: "submitted" } | { type: "failed"; payload: {
	reason: string,
} } | { type: "historyLoading" } | { type: "historyLoaded"; payload: {
	reports: ModerationReportSummary[],
} } | { type: "historyFailed"; payload: {
	reason: string,
} };

export type ReportingState = {
	open: boolean,
	playerId: number | null,
	login: string,
	status: ReportStatus,
	history: ModerationReportSummary[],
	historyStatus: ReportHistoryStatus,
};

export type RequestFailureKind =
/**  The access token is absent, expired, or rejected by the service. */
"unauthorized" |
/**  The service cannot currently be reached, including server-side 5xx. */
"offline" |
/**  The requested endpoint or resource does not exist. */
"notFound" |
/**  The service understood the request but refused it. */
"rejected" |
/**  Configuration, decoding, or another client-side invariant failed. */
"unexpected";

/**
 *  Scrollback detached from a channel that is no longer joined. Deliberately
 *  excludes topic, roster and unread state: those are live server facts and
 *  must be rebuilt when the channel is joined again.
 */
export type RetainedChatHistory = {
	channel: string,
	messages: ChatMessage[],
};

/**  One person's review. */
export type Review = {
	id: number,
	/**  1–5. */
	score: number,
	text: string,
	/**  The reviewer's login. Empty when the API did not resolve the player. */
	player: string,
	/**
	 *  Which version of the map or mod was reviewed: a two-year-old review of
	 *  version 1 says little about version 9.
	 */
	version: string,
};

/**
 *  What is being reviewed. Maps and mods have separate API resources with
 *  identical shapes, so the kind travels with the id rather than forking every
 *  type in this module.
 */
export type ReviewKind = "map" | "mod";

/**
 *  Whether a write is in flight. Separate from the read status so a failed
 *  submission does not blank the list the user is looking at.
 */
export type ReviewSubmitStatus = { type: "idle" } | { type: "saving" } | { type: "saved" } | { type: "failed"; payload: {
	reason: string,
} };

/**  The score distribution, as both reference clients present it. */
export type ReviewSummary = {
	total: number,
	/**
	 *  Mean score in tenths: `43` is 4.3 stars.
	 *
	 *  An integer rather than a float because specta cannot express a plain
	 *  `f32` across the IPC boundary (it becomes `number | null`, since JSON
	 *  has no NaN), and because the codebase already carries averages this way
	 * : see `VaultMap::rating_tenths`. Zero when nothing has been reviewed.
	 */
	averageTenths: number,
	/**  How many reviews gave each score, indexed one star to five. */
	counts: number[],
};

/**  Which map or mod's reviews are open. */
export type ReviewTarget = {
	kind: ReviewKind,
	id: number,
	/**  Shown in the panel heading so it can open before the reviews arrive. */
	name: string,
};

export type ReviewsCommand =
/**  Open the panel for a map or mod and load its reviews. */
{ type: "open"; payload: {
	target: ReviewTarget,
} } | { type: "close" } |
/**  Write or replace the signed-in player's review. */
{ type: "submit"; payload: {
	score: number,
	text: string,
} } |
/**  Withdraw the signed-in player's review. */
{ type: "delete" };

export type ReviewsEvent = { type: "opened"; payload: {
	target: ReviewTarget,
} } | { type: "closed" } | { type: "loading" } | { type: "loaded"; payload: {
	target: ReviewTarget,
	reviews: Review[],
} } | { type: "loadFailed"; payload: {
	reason: string,
} } | { type: "saving" } |
/**  The write landed; `reviews` is the refreshed list. */
{ type: "saved"; payload: {
	reviews: Review[],
} } | { type: "saveFailed"; payload: {
	reason: string,
} };

export type ReviewsState = {
	/**  `None` when the panel is closed. */
	target: ReviewTarget | null,
	reviews: Review[],
	summary: ReviewSummary,
	status: ReviewsStatus,
	submit: ReviewSubmitStatus,
};

export type ReviewsStatus = { type: "idle" } | { type: "loading" } | { type: "ready" } | { type: "failed"; payload: {
	reason: string,
} };

export type SeasonLeaderboard = {
	entries: LeaderboardEntry[],
	tiers: LeaderboardTier[],
};

/**  Things the UI can ask the session service to do. */
export type SessionCommand =
/**  Handshake: ask the backend to report readiness. */
{ type: "hello" };

/**  Things that have happened to the session. The only way [`SessionState`] changes. */
export type SessionEvent = { type: "connecting" } | { type: "backendReady"; payload: {
	version: string,
	offlineAuth: boolean,
} } | { type: "disconnected" };

/**  State of the session slice. */
export type SessionState = {
	/**  Version reported by the Rust backend once it is ready. */
	backendVersion: string,
	status: ConnectionStatus,
	/**
	 *  Whether this process is wired to the offline development ports
	 *  (`FAF_FAKE_AUTH=1`), rather than the real FAF services.
	 *
	 *  The credential-free test login only produces a usable session in that
	 *  build: against real ports it fabricates a player the server has never
	 *  heard of, with no token behind it, so every subsequent request fails in
	 *  a way that looks like the client is broken. The UI uses this to decide
	 *  whether to offer it at all.
	 */
	offlineAuth: boolean,
};

export type SettingsCommand = { type: "load" } | { type: "setTheme"; payload: {
	theme: Theme,
} } | { type: "setGamePath"; payload: {
	path: string,
} } | { type: "setReplayGamePath"; payload: {
	path: string,
} } | { type: "setGeneral"; payload: {
	preferences: GeneralPreferences,
} } | { type: "setAppearance"; payload: {
	preferences: AppearancePreferences,
} } | { type: "setPlayerNote"; payload: {
	player_id: number,
	login: string,
	note: string,
} } | { type: "setNotifications"; payload: {
	preferences: NotificationPreferences,
} } | { type: "setChat"; payload: {
	preferences: ChatPreferences,
} } | { type: "setGame"; payload: {
	preferences: GamePreferences,
} } | { type: "setDiscord"; payload: {
	preferences: DiscordPreferences,
} } | { type: "setConnectivity"; payload: {
	preferences: ConnectivityPreferences,
} } | { type: "setUpdates"; payload: {
	preferences: UpdatePreferences,
} } | { type: "setBrowsing"; payload: {
	preferences: BrowsingPreferences,
} } | { type: "checkInstalls" };

export type SettingsEvent = { type: "loaded"; payload: {
	settings: SettingsState,
} } | { type: "themeChanged"; payload: {
	theme: Theme,
} } | { type: "gamePathChanged"; payload: {
	path: string,
} } | { type: "replayGamePathChanged"; payload: {
	path: string,
} } | { type: "generalChanged"; payload: {
	preferences: GeneralPreferences,
} } | { type: "appearanceChanged"; payload: {
	preferences: AppearancePreferences,
} } | { type: "socialChanged"; payload: {
	preferences: SocialPreferences,
} } | { type: "notificationsChanged"; payload: {
	preferences: NotificationPreferences,
} } | { type: "chatChanged"; payload: {
	preferences: ChatPreferences,
} } | { type: "gameChanged"; payload: {
	preferences: GamePreferences,
} } | { type: "discordChanged"; payload: {
	preferences: DiscordPreferences,
} } | { type: "connectivityChanged"; payload: {
	preferences: ConnectivityPreferences,
} } | { type: "updatesChanged"; payload: {
	preferences: UpdatePreferences,
} } | { type: "browsingChanged"; payload: {
	preferences: BrowsingPreferences,
} };

/**
 *  Persisted preferences. `#[serde(default)]` is essential for forward
 *  compatibility: settings files written by older builds only contain the
 *  original theme/path fields and must retain them while new groups default.
 */
export type SettingsState = {
	theme: Theme,
	gamePath: string,
	replayGamePath: string,
	general: GeneralPreferences,
	appearance: AppearancePreferences,
	social: SocialPreferences,
	notifications: NotificationPreferences,
	chat: ChatPreferences,
	game: GamePreferences,
	discord: DiscordPreferences,
	connectivity: ConnectivityPreferences,
	updates: UpdatePreferences,
	browsing: BrowsingPreferences,
};

export type SocialCommand =
/**
 *  Add or remove a friend/foe.
 *
 *  Carries `login` alongside `player_id` because the wire command addresses
 *  the player by id while our own state is keyed by name: the same posture
 *  as `ChatCommand::Connect` carrying the UI-known username rather than
 *  making the backend look it up.
 */
{ type: "setRelation"; payload: {
	playerId: number,
	login: string,
	relation: Relation,
	member: boolean,
} };

export type SocialEvent =
/**  A full replacement of both relation lists (the lobby sends them together). */
{ type: "relationsUpdated"; payload: {
	friends: string[],
	foes: string[],
} } |
/**
 *  One relation was added or removed. Emitted optimistically when the user
 *  acts, because `social_add`/`social_remove` are fire-and-forget: the
 *  server does not echo a fresh `social` message back, so both reference
 *  clients update their local set at the point of action too.
 */
{ type: "relationSet"; payload: {
	login: string,
	relation: Relation,
	member: boolean,
} } |
/**
 *  Profiles newly seen or changed. Merged into the existing set by login,
 *  not replacing it.
 */
{ type: "playersSeen"; payload: {
	players: PlayerProfile[],
} } |
/**
 *  Profiles authoritatively marked offline by `player_info`. Relations are
 *  retained: going offline does not stop somebody being a friend or foe.
 */
{ type: "playersRemoved"; payload: {
	logins: string[],
} } |
/**  The lobby connection went away; relations are no longer authoritative. */
{ type: "cleared" };

export type SocialPreferences = {
	playerNotes: PlayerNote[],
};

export type SocialState = {
	/**  Logins of players on our friends list, sorted. */
	friends: string[],
	/**  Logins of players on our foes list, sorted. */
	foes: string[],
	/**  Every FAF account currently announced online, sorted by login. */
	players: PlayerProfile[],
};

/**
 *  Where the season statistics stand.
 *
 *  A separate status from [`GalacticWarStatus`] on purpose. The statistics are
 *  decoration; installing and launching is the point of the tab. A gateway
 *  that is unreachable, or that has moved its schema past what we decode, must
 *  never take the Play button with it.
 */
export type StatisticsStatus = { type: "idle" } | { type: "loading" } | { type: "loaded" } | { type: "failed"; payload: {
	reason: string,
} };

/**
 *  A top-level destination. Most are placeholders today; each gets its feature
 *  slice as it lands. The frontend tab registry maps these 1:1 to views.
 */
export type Tab = "news" | "chat" | "play" | "replays" | "maps" | "mods" | "leaderboard" | "tournaments" | "tutorials" | "units" | "contribution" | "settings";

export type Theme = "forgeDark" | "forgeLight" | "javaClient" | "pythonClient";

/**
 *  One tournament, as the FAF API's `/challonge/v1/tournaments.json` bridge
 *  reports it.
 *
 *  Timestamps are Unix seconds rather than the API's ISO strings so the status
 *  derivation is a comparison instead of date parsing: this crate is pure and
 *  has no clock, no time zone database, and no date library.
 */
export type Tournament = {
	id: number,
	name: string,
	/**
	 *  Free text from the organiser. Challonge stores it as HTML; it arrives
	 *  here already reduced to plain text (see `protocol::tournaments`),
	 *  because rendering third-party markup would mean trusting an organiser
	 *  with script execution inside the client.
	 */
	description: string,
	/**  Challonge's own name for the format: `single elimination`, `swiss`, … */
	tournamentType: string,
	participantCount: number,
	createdAt: number | null,
	startingAt: number | null,
	completedAt: number | null,
	challongeUrl: string,
	liveImageUrl: string,
	signUpUrl: string,
	openForSignup: boolean,
};

export type TournamentsCommand = { type: "load" } | { type: "select"; payload: {
	tournamentId: number,
} };

export type TournamentsEvent = { type: "loading" } | { type: "loaded"; payload: {
	tournaments: Tournament[],
} } | { type: "loadFailed"; payload: {
	reason: string,
} } | { type: "selected"; payload: {
	tournamentId: number,
} };

export type TournamentsState = {
	tournaments: Tournament[],
	status: TournamentsStatus,
	/**
	 *  Which event's detail pane is open. `None` until the first load picks
	 *  one, matching the Java client selecting the first row automatically.
	 */
	selectedId: number | null,
};

export type TournamentsStatus = { type: "idle" } | { type: "loading" } | { type: "ready" } | { type: "failed"; payload: {
	reason: string,
} };

/**  One lesson. */
export type Tutorial = {
	id: number,
	title: string,
	/**  Already reduced to plain text; the API stores it as HTML. */
	description: string,
	/**
	 *  The first `https://` destination the description linked to, or empty.
	 *
	 *  FAF publishes whole categories: "Video tutorials", "Written guides",
	 *  whose entries are not playable maps at all but pointers to YouTube and
	 *  the wiki. Reducing the description to plain text keeps their prose and
	 *  throws away the only thing they are for, which left most of the tab
	 *  showing rows labelled "unavailable" that did nothing when clicked.
	 */
	linkUrl: string,
	imageUrl: string,
	/**  Position within its category, as the API orders them. */
	ordinal: number,
	/**
	 *  Whether the server considers this one playable. A tutorial can be
	 *  listed for reference while its map is being replaced.
	 */
	launchable: boolean,
	/**  The map the lesson runs on: needed before launching. */
	mapFolderName: string,
	/**  The scenario name passed to the game as `/map`. */
	technicalName: string,
	categoryId: number | null,
};

/**  A group of lessons: "Basics", "Build order", and so on. */
export type TutorialCategory = {
	id: number,
	name: string,
};

/**
 *  Where a launch stands. Its own status because the wait is long: the
 *  `tutorials` featured mod has to be patched and the map downloaded first.
 */
export type TutorialLaunchStatus = { type: "idle" } | { type: "preparing"; payload: {
	tutorialId: number,
	detail: string,
} } | { type: "launched"; payload: {
	tutorialId: number,
} } | { type: "failed"; payload: {
	reason: string,
} };

export type TutorialsCommand = { type: "load" } | { type: "select"; payload: {
	tutorialId: number,
} } | { type: "launch"; payload: {
	tutorialId: number,
} };

export type TutorialsEvent = { type: "loading" } | { type: "loaded"; payload: {
	categories: TutorialCategory[],
	tutorials: Tutorial[],
} } | { type: "loadFailed"; payload: {
	reason: string,
} } | { type: "selected"; payload: {
	tutorialId: number,
} } | { type: "launchPreparing"; payload: {
	tutorialId: number,
	detail: string,
} } | { type: "launched"; payload: {
	tutorialId: number,
} } | { type: "launchFailed"; payload: {
	reason: string,
} };

export type TutorialsState = {
	categories: TutorialCategory[],
	tutorials: Tutorial[],
	status: TutorialsStatus,
	selectedId: number | null,
	launch: TutorialLaunchStatus,
};

export type TutorialsStatus = { type: "idle" } | { type: "loading" } | { type: "ready" } | { type: "failed"; payload: {
	reason: string,
} };

/**  Someone composing a message, and when we last heard so. */
export type TypingNotice = {
	nickname: string,
	/**
	 *  Unix seconds. `u32` because specta rejects 64-bit integers on this
	 *  boundary; it overflows in 2106, which is not this decade's problem.
	 */
	atSeconds: number,
};

export type UiDensity = "compact" | "comfortable";

/**  Client self-update: whether to look for a newer build, and which ones count. */
export type UpdatePreferences = {
	/**
	 *  Check for a newer release at startup.
	 *
	 *  Defaulted on, matching the Java client, which checks unconditionally.
	 *  The switch exists because the check is an outbound request to GitHub
	 *  that some users would rather not make on every launch.
	 */
	automatic: boolean,
	/**
	 *  Also offer prereleases. Java's `preReleaseCheckEnabled`, where it picks
	 *  between two entirely separate check tasks.
	 */
	preRelease: boolean,
};

export type UploadKind = "map" | "mod";

/**  What the user asked to publish. */
export type UploadRequest = {
	kind: UploadKind,
	/**  The folder inside the user's maps/mods directory. */
	folderName: string,
	/**  What to call it in the UI while it uploads. */
	displayName: string,
	/**
	 *  Maps only: whether the author wants it rated. Ignored for mods, which
	 *  have no equivalent flag in either reference client.
	 */
	ranked: boolean,
};

/**
 *  How far along a publish is.
 *
 *  Zipping and uploading are separate stages because they fail for entirely
 *  different reasons: a missing folder versus a rejected archive: and
 *  because zipping a large map is slow enough that a single "working…" would
 *  look hung.
 */
export type UploadStatus = { type: "idle" } | { type: "compressing" } |
/**  Bytes sent so far, and the archive's total size. */
{ type: "uploading"; payload: {
	sentBytes: number,
	totalBytes: number,
} } |
/**  Mods only: the archive is in storage and the API is being told. */
{ type: "finishing" } | { type: "succeeded" } | { type: "failed"; payload: {
	reason: string,
} };

export type UploadsCommand = { type: "open"; payload: {
	request: UploadRequest,
} } | { type: "close" } | { type: "setRanked"; payload: {
	ranked: boolean,
} } |
/**  Publish whatever the dialog currently describes. */
{ type: "start" };

export type UploadsEvent = { type: "opened"; payload: {
	request: UploadRequest,
} } | { type: "closed" } | { type: "rankedChanged"; payload: {
	ranked: boolean,
} } | { type: "progressed"; payload: {
	status: UploadStatus,
} };

export type UploadsState = {
	/**  The publish dialog's subject, or `None` when it is closed. */
	request: UploadRequest | null,
	status: UploadStatus,
};

/**
 *  One map version, as listed from the FAF Data API (`GET /data/map`,
 *  `include=latestVersion,author`). Mirrors the Python client's `Map` +
 *  `MapVersion` models (`src/api/models/Map.py`, `MapVersion.py`): the
 *  client always looks at `map.latestVersion`, never older versions.
 */
export type VaultMap = {
	mapId: number,
	versionId: number,
	displayName: string,
	/**
	 *  `None` for maps without an uploader on record (mirrors `Map.author`
	 *  being optional in the Python model).
	 */
	author: string | null,
	/**
	 *  The directory name this version installs as, e.g. `scmp_009.v0001`,
	 *  the install/uninstall/"is this installed" key everywhere (mirrors
	 *  `MapVersion.folder_name`).
	 */
	folderName: string,
	version: string,
	description: string,
	mapType: string,
	maxPlayers: number,
	width: number,
	height: number,
	gamesPlayed: number,
	versionGamesPlayed: number,
	ranked: boolean,
	recommended: boolean,
	/**  Average community review score in tenths (for example, `43` = 4.3). */
	ratingTenths: number,
	reviews: number,
	/**  ISO-8601 creation timestamp from the latest map version. */
	createdAt: string,
	downloadUrl: string,
	thumbnailUrl: string,
	thumbnailUrlLarge: string,
};

/**
 *  One mod version, as listed from the FAF Data API (`GET /data/mod`,
 *  `include=latestVersion`): the client always looks at `mod.latestVersion`,
 *  same posture as [`crate::state::VaultMap`].
 */
export type VaultMod = {
	modId: number,
	versionId: number,
	displayName: string,
	/**
	 *  Flat attribute on the `mod` resource itself, not a relationship
	 *  (unlike [`crate::state::VaultMap`]'s `author`, which is a `player`
	 *  relationship): confirmed against the Java client's `Mod.author`.
	 */
	author: string,
	uploader: string,
	/**
	 *  `latestVersion.uid`: the stable id matched against locally
	 *  installed mods and `game.prefs`'s `active_mods` table. Distinct
	 *  from the numeric JSON:API resource `id`.
	 */
	uid: string,
	/**
	 *  Stored as text: FAF mod versions aren't reliably semver (often a
	 *  bare integer).
	 */
	version: string,
	description: string,
	filename: string,
	modType: ModType,
	ranked: boolean,
	recommended: boolean,
	/**  Average community review score in tenths (for example, `43` = 4.3). */
	ratingTenths: number,
	reviews: number,
	createdAt: string,
	updatedAt: string,
	downloadUrl: string,
	thumbnailUrl: string,
};

/**
 *  One entry in the global "newest replays" feed, as listed from the FAF
 *  Data API (`GET /data/game`, no player filter: mirrors the Java client's
 *  `OnlineReplayVaultController`'s `NEWEST` category). Just enough to render
 *  a row and trigger a download+play: not the full search/filter model the
 *  reference clients' vault tabs have (map/player/rating filters, "own
 *  replays only" toggle, are a later phase).
 */
export type VaultReplay = {
	uid: number,
	/**
	 *  `game.attributes.name`: the host-chosen lobby title (e.g. "all
	 *  welcome", "1200+"), distinct from the map name.
	 */
	title: string,
	map: string,
	/**
	 *  `mapVersion.thumbnailUrlSmall` straight from the API. Empty string if
	 *  missing (e.g. a generated/hidden map): the frontend treats that as
	 *  "no thumbnail" rather than us modeling it as `Option`.
	 */
	mapThumbnailUrl: string,
	modName: string,
	/**  ISO 8601, straight from the API: rendering/formatting is a UI concern. */
	startTime: string,
	/**
	 *  Whether the file has actually finished uploading to content storage.
	 *  A "newest replays" listing includes very recent/still-processing
	 *  games too; both reference clients disable the Watch button until this
	 *  is `true` rather than filtering the row out entirely.
	 */
	replayAvailable: boolean,
	/**
	 *  `endTime - startTime` in seconds. `None` if either timestamp is
	 *  missing/unparseable (e.g. a game still in progress has no `endTime`).
	 */
	durationSeconds: number | null,
	/**
	 *  Simulation time from `replayTicks` (10 ticks/second). Unlike the wall
	 *  clock duration above, this excludes pauses and slow simulation speed.
	 */
	gameDurationSeconds: number | null,
	teams: ReplayTeam[],
	/**
	 *  Average of all resolvable player ratings on the card: `None` if no
	 *  player's rating could be resolved.
	 */
	averageRating: number | null,
	reviewsAverage: number | null,
	reviewsCount: number | null,
};

/**
 *  Where the vault list stands. Separate from [`ReplayStatus`] (playback),
 *  you can be browsing the vault (`Ready`) while also `Playing` a replay.
 */
export type VaultStatus = { type: "idle" } | { type: "loading" } | { type: "ready" } | { type: "failed"; payload: {
	reason: string,
} };
